INSERT INTO NewsletterCampaign (id, subject, name, previewLine, body, status, sentAt, createdAt, updatedAt, targetList, recipientsCount, opensCount, clicksCount, visible, fromName, fromEmail, replyToName, replyToEmail, bcc, bounceEmail, attachments, trackingEnabled) VALUES ('459f71d5-2365-4713-bb16-8a79d88e0836', 'Schnupper- und Grundkurse können stattfinden // B-Theorie am WE noch Plätze frei // Flugschulberatung in Landau möglich', 'Schnupper- und Grundkurse können stattfinden // B-Theorie am WE noch Plätze frei // Flugschulberatung in Landau möglich', NULL, '<div style="text-align: center; width: 100%; background-color: #fff;">
<table style="text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;" cellspacing="0" cellpadding="0" align="center" bgcolor="#ebebeb">
<tbody class="acyeditor_sortable">
<tr style="line-height: 0px;">
<td style="background-color: #69b4c0; height: 38px;" valign="bottom"><img src="media/com_acymailing/templates/newsletter-4/top.png" alt=" - - - " width="600" height="38" /></td>
</tr>
<tr>
<td style="text-align: center; width: 600px;">
<table border="0" style="margin: auto; width: 600px;" cellspacing="0" cellpadding="0">
<tbody class="acyeditor_sortable">
<tr class="acyeditor_delete">
