INSERT INTO NewsletterCampaign (id, subject, name, previewLine, body, status, sentAt, createdAt, updatedAt, targetList, recipientsCount, opensCount, clicksCount, visible, fromName, fromEmail, replyToName, replyToEmail, bcc, bounceEmail, attachments, trackingEnabled) VALUES ('c524ef70-889d-41cc-a062-cf64c01d26a5', 'Morgen 7.6. Flugschule geöffnet / Pfalztour 1 ausgebucht - 2. Tour noch Plätze frei / Windentheorie am 20.6.', 'Morgen 7.6. Flugschule geöffnet / Pfalztour 1 ausgebucht - 2. Tour noch Plätze frei / Windentheorie am 20.6.', NULL, '<div style="text-align: center; width: 100%; background-color: #fff;">
<table style="text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;" cellspacing="0" cellpadding="0" align="center" bgcolor="#ebebeb">
