INSERT INTO NewsletterCampaign (id, subject, name, previewLine, body, status, sentAt, createdAt, updatedAt, targetList, recipientsCount, opensCount, clicksCount, visible, fromName, fromEmail, replyToName, replyToEmail, bcc, bounceEmail, attachments, trackingEnabled) VALUES ('3e57769f-fce2-4c3e-9ef7-ea9442e70e98', 'Tandemflüge am Donnerstag, 12.5.22  in Heidelberg', 'Tandemflüge am Donnerstag, 12.5.22  in Heidelberg', 'Termine von 13-18 Uhr', '<div style="text-align: center; width: 100%; background-color: #fff;">
<table style="text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;" cellspacing="0" cellpadding="0" align="center" bgcolor="#ebebeb">
