INSERT INTO NewsletterCampaign (id, subject, name, previewLine, body, status, sentAt, createdAt, updatedAt, targetList, recipientsCount, opensCount, clicksCount, visible, fromName, fromEmail, replyToName, replyToEmail, bcc, bounceEmail, attachments, trackingEnabled) VALUES ('31010f5e-b0f5-479e-9a87-6eebd99f64e3', 'Reisen 2023: Kolumbientermin steht fest: 21.1-4.2.23', 'Reisen 2023: Kolumbientermin steht fest: 21.1-4.2.23', 'Fliegen über den sattgrünen Landschaften der besten Fluggebiete des Valle del Cauca', '<div style="text-align: center; width: 100%; background-color: #fff;">
<table style="text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;" cellspacing="0" cellpadding="0" align="center" bgcolor="#ebebeb">
<tbody class="acyeditor_sortable">
<tr style="line-height: 0px;">
<td style="background-color: #69b4c0; height: 38px;" valign="bottom"><img src="media/com_acymailing/templates/newsletter-4/top.png" alt=" - - - " width="600" height="38" /></td>
</tr>
<tr>
<td style="text-align: center; width: 600px;">
<table border="0" style="margin: auto; width: 600px;" cellspacing="0" cellpadding="0">
<tbody class="acyeditor_sortable">
<tr class="acyeditor_delete">
<td style="background-color: #ebebeb; width: 40px;">&nbsp;</td>
<td class="acyeditor_text" style="padding: 20px 0px; text-align: left; background-color: #ebebeb; width: 520px;"><img src="media/com_acymailing/templates/newsletter-4/message_icon.png" alt="-" width="41" height="41" style="margin: 0px 10px; float: left;" />
<h3><span style="color: #3491b7;">NEWSLETTER</span></h3>
</td>
</tr>
</tbody>
<tbody class="acyeditor_sortable">
<tr>
<td style="background-color: #ebebeb; width: 40px;">&nbsp;</td>
<td class="acyeditor_text" style="padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;"><a href="http://www.flugschule-hirondelle.de/" target="_blank" rel="noopener noreferrer"><img src="images/Logo-H-web.jpg" alt="" width="285" height="92" /></a></td>
<td style="background-color: #ebebeb; width: 40px;">
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
</td>
</tr>
<tr class="acyeditor_delete">
<td style="background-color: #ebebeb; width: 40px;">&nbsp;</td>
<td class="acyeditor_text" style="background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 520px; margin: 15px auto;">
<h3 style="text-align: left;"><span style="color: #3491b7;">Hallo {subtag:name|part:first|ucfirst},</span></h3>
<p style="text-align: left;">unsere Reise nach Kolumbien 2023 steht 😊. Wir<span class="Apple-converted-space"></span>freuen uns, mit euch Ende Januar / Anfang Februar wieder über die sattgrünen Landschaften des Valle del Cauca fliegen zu dürfen. Dabei befliegen wir über mehrere Stationen die besten Fluggebiete von Cali in Richtung Medellin.&nbsp;</p>
<p style="text-align: left;">&nbsp;<img src="images/1-Bilderfuernewsletter/Kolumbien_Collage.jpg" alt="" width="500" height="500" /></p>
<p style="text-align: left;">Für alle was dabei - ob stundenlanges Hausbergfliegen in oft super schöner Thermik mit vielen gefiederten Kollegen (auf pfälzisch - Geiern 😄) oder Streckenfliegen inkl. lustiger Rückholaktionen mitten aus der Pampa durch unsere Rückhohler oder hinten auf dem Einheimischen-Moped oder oder oder - echt genial 😅!<br /> <br /> Nach dem Flugtag genießen wir den Rest des Tages in unserer Finca am Pool bei einem Glas Rum-Maracuja und oder gehen mit euch lecker Essen.<br /> <br /> Für alle, die sich für die neue Saison schon mal einfliegen oder satt fliegen wollen 😉!<span class="Apple-converted-space">&nbsp; </span>Man kann es echt krachen lassen im Valle del Cauca… ☺️!&nbsp;Hier ein kleiner Vorgeschmack in Form meiner Airtime in diesem Jahr:</p>
<p style="text-align: left;">&nbsp;<img src="images/1-Bilderfuernewsletter/Kolumbien_Airtime.png" alt="" width="500" height="198" /></p>
<p style="text-align: left;">Abflug ist mit Lufthansa am 21.1.23 in Frankfurt um 12:50 Uhr mit Zwischenstopp über Bogota und Ankunft in Cali um 21:27 Uhr lokale Zeit. Dann gehts in ca. 45 min zu unserer Finca. Dann einmal richtig ausschlafen und am nächsten Tag sind wir direkt good to go und fliegen in unserem ersten Stop in Piedechinche. Da können wir uns dann erstmal gemütlich einfliegen. Ein super einfacher Start- und Landeplatz mit Fliegerbar und Packservice für die Schirme… besser geht’s fast nicht ;-)…</p>
<p style="text-align: left;">Mehr Infos zur Reise findet ihr hier:</p>
<p style="text-align: left;"><a href="https://www.fs-hirondelle.de/reisen-touren/kolumbien">https://www.fs-hirondelle.de/reisen-touren/kolumbien</a></p>
<p style="text-align: left;">Und hier geht''s gleich zur Buchung:&nbsp;<a href="https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/14-reisen/1126-kolumbien-tour">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/14-reisen/1126-kolumbien-tour</a></p>
<p style="text-align: left;">Wir freuen uns wenn ihr dabei seid!</p>
<p style="text-align: left;"><em style="color: #3491b7;"><strong>Luftige Grüße </strong></em></p>
<p style="text-align: left;"><em style="color: #3491b7;"><strong>Sarah &amp; Alex</strong></em></p>
<p style="text-align: left;"><em style="color: #3491b7;"></em><strong style="color: #3491b7; text-align: left;"><em>Team Hirondelle</em></strong></p>
<hr />
<p style="text-align: left;"><em>Hinweis CORONA:<br /></em><em>Wir empfehlen dringend den Abschluss einer Reiserücktritts- <br />sowie einer Auslandskrankenversicherung.&nbsp;</em></p>
<hr />
<p><span style="font-size: small;"><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br /></strong></span></p>
<p style="line-height: 100%; margin: 1px; text-align: center;"><span style="font-weight: bold;"><span style="font-size: xx-small;"><span style="font-weight: bold; font-family: Arial,''Arial Unicode MS'',Helvetica,sans-serif;">Flugschule Hirondelle</span><br /></span><span style="font-size: 14px; font-family: Arial, ''Arial Unicode MS'', Helvetica, sans-serif;"><span style="font-size: xx-small;">Untergasse 27 -&nbsp; 69469 Weinheim &nbsp;| &nbsp;Am Birnbach 6 - 76829 Landau<br /></span></span></span></p>
<p style="line-height: 100%; margin: 1px; text-align: center;">&nbsp;</p>
