INSERT INTO NewsletterCampaign (id, subject, name, previewLine, body, status, sentAt, createdAt, updatedAt, targetList, recipientsCount, opensCount, clicksCount, visible, fromName, fromEmail, replyToName, replyToEmail, bcc, bounceEmail, attachments, trackingEnabled) VALUES ('9e79193c-cedf-4a72-b80f-32c7f823fcfc', 'Newsletter der Flugschule Hirondelle', 'Grundkursschulung am WE 8.-9.10.22', NULL, '<div style="text-align: center; width: 100%; background-color: #fff;">
<table style="text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;" cellspacing="0" cellpadding="0" align="center" bgcolor="#ebebeb">
