INSERT INTO NewsletterCampaign (id, subject, name, previewLine, body, status, sentAt, createdAt, updatedAt, targetList, recipientsCount, opensCount, clicksCount, visible, fromName, fromEmail, replyToName, replyToEmail, bcc, bounceEmail, attachments, trackingEnabled) VALUES ('143885ba-11b5-4ddd-bac7-20dcfa1623ac', 'Donnerstag. 24.11.22 Flugschule geöffnet // Kalender 2023 online', 'Donnerstag. 24.11.22 Flugschule geöffnet // Kalender 2023 online', 'Die Termine 2023 sind online und ab sofort buchbar // Wir sind dann mal weg... Betriebsurlaub bis 18.12.2022', '<div style="text-align: center; width: 100%; background-color: #fff;">
<table style="text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;" cellspacing="0" cellpadding="0" align="center" bgcolor="#ebebeb">
