INSERT INTO NewsletterCampaign (id, subject, name, previewLine, body, status, sentAt, createdAt, updatedAt, targetList, recipientsCount, opensCount, clicksCount, visible, fromName, fromEmail, replyToName, replyToEmail, bcc, bounceEmail, attachments, trackingEnabled) VALUES ('466863bc-0c07-4deb-87e0-7ea94bc62921', 'Flugschule geöffnet Mittwoch, 18.6.25  15-19 Uhr', 'Flugschule geöffnet Mittwoch, 18.6.25  15-19 Uhr', 'Letzte Plätze bei 2025er Touren: XC-Seminar, Sicherheitstraining und Pfalztour // Fernreisen 2026: Termine stehen für Kolumbien 🇨🇴 und Südafrika 🇿🇦', '<div style="text-align: center; width: 100%; background-color: #fff;">
<table style="text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;" cellspacing="0" cellpadding="0" align="center" bgcolor="#ebebeb">
