INSERT INTO NewsletterCampaign (id, subject, name, previewLine, body, status, sentAt, createdAt, updatedAt, targetList, recipientsCount, opensCount, clicksCount, visible, fromName, fromEmail, replyToName, replyToEmail, bcc, bounceEmail, attachments, trackingEnabled) VALUES ('98edee74-2b13-419b-bb1a-b0323a91571c', 'Tandemflüge am Freitag, 3.7.26 in Heidelberg', 'Tandemflüge am Freitag, 3.7.26 in Heidelberg', 'Termine von  12 bis 15.45 Uhr', '<div style="text-align: center; width: 100%; background-color: #fff;">
<table style="text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;" cellspacing="0" cellpadding="0" align="center" bgcolor="#ebebeb">
