INSERT INTO NewsletterCampaign (id, subject, name, previewLine, body, status, sentAt, createdAt, updatedAt, targetList, recipientsCount, opensCount, clicksCount, visible, fromName, fromEmail, replyToName, replyToEmail, bcc, bounceEmail, attachments, trackingEnabled) VALUES ('3243db43-2585-4560-9a66-c90288ad99ea', 'Flugschule geöffnet Donnerstag, 16.7.26  16 - 19 Uhr', 'Flugschule geöffnet Donnerstag, 16.7.26  16 - 19 Uhr', 'Bassano-Tour 2 🇮🇹 Thermik / Technik / Strecke: 18. – 24.10.26 1 Platz frei', '<div style="text-align: center; width: 100%; background-color: #fff;">
<table style="text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;" cellspacing="0" cellpadding="0" align="center" bgcolor="#ebebeb">
<tbody class="acyeditor_sortable">
<tr style="line-height: 0px;">
<td style="background-color: #69b4c0; height: 38px;" valign="bottom"><img src="media/com_acymailing/templates/newsletter-4/top.png" alt="- - -" width="600" height="38"></td>
</tr>
<tr>
<td style="text-align: center; width: 600px;">
<table style="margin: auto; width: 600px;" border="0" cellspacing="0" cellpadding="0">
<tbody class="acyeditor_sortable">
<tr class="acyeditor_delete">
<td style="background-color: #ebebeb; width: 40px;"> </td>
<td class="acyeditor_text" style="padding: 20px 0px; text-align: left; background-color: #ebebeb; width: 520px;"><img style="margin: 0px 10px; float: left;" src="media/com_acymailing/templates/newsletter-4/message_icon.png" alt="-" width="41" height="41">
<h3><span style="color: #3491b7;">NEWSLETTER</span></h3>
</td>
</tr>
</tbody>
<tbody class="acyeditor_sortable">
<tr>
<td style="background-color: #ebebeb; width: 40px;"> </td>
<td class="acyeditor_text" style="padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;"><a href="http://www.flugschule-hirondelle.de/" target="_blank" rel="noopener noreferrer"><img src="images/Logo-H-web.jpg" alt="" width="285" height="92"></a></td>
<td style="background-color: #ebebeb; width: 40px;">
<p> </p>
<p> </p>
<p> </p>
</td>
</tr>
<tr class="acyeditor_delete">
<td style="background-color: #ebebeb; width: 40px;"> </td>
<td class="acyeditor_text" style="background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 520px; margin: 15px auto;">
<h3 style="text-align: left;"><span style="color: #3491b7;">Hallo {subtag:name|part:first|ucfirst},</span></h3>
<p style="text-align: left;">diese Woche Donnerstag, 16.7.26 sind wir wieder für euch in der Flugschule in Weinheim von 16 - 19 Uhr. Egal was ihr braucht oder wenn ihr Fragen habt – wir sind für euch da! </p>
<p style="text-align: left;"><strong style="font-family: inherit; font-size: 1rem;">Meldet euch bitte unbedingt vorab bei uns per E-Mail 📧 mit eurer Wunschuhrzeit und eurem Anliegen an</strong><span style="font-family: inherit; font-size: 1rem;">, damit wir auch etwas Zeit für euch haben - und nicht alle auf einmal dastehen. In letzter Zeit hatten wir oft volles Haus, da doch einige unangemeldet dazu kamen 😉</span></p>
<p><em>☝🏼Bitte unbedingt beachten: <br><em>b<em>itte in den umliegenden Straßen parken,</em></em><br>die Parkplätze 🅿️  im Hof der Flugschule sind nur für</em><em> Anwohner! </em></p>
<p style="text-align: left;">Ab dem Wochenende sind wir dann erstmal in Frankreich 🇫🇷 für einen weiteren Wettkampf von Alex. Von dort geht es dann direkt nach Italien 🇮🇹 zur Höhenflugschulung und weiter nach Slowenien 🇸🇮 zum Thermik-/Strecken-Camp. </p>
<p style="text-align: left;">Alle, die noch ein Reiseziel für Oktober suchen: Wir haben gerade ein Storno für unsere Bassano-Reise reingekriegt. Die Reise ist ideal für erste Thermik-/Streckenerfahrungen, also z. B. auch den B-Schein Streckenflug. Oder einfach noch mal vor dem Winter und der Saure-Gurken-Zeit ordentlich in die Luft kommen und das Dolce Vita in Italien 🇮🇹 mit Pizza 🍕Pasta 🍝 und Co. genießen! Hier gibt''s weitere Infos:</p>
<p style="text-align: left;"><strong>➡️ Bassano-Tour 2 </strong>🇮🇹<strong> Thermik / Technik / Strecke: 18. – 24.10.2</strong><strong>6 <span style="color: rgb(45, 194, 107);">1 Platz</span></strong></p>
<p style="text-align: left;"><span style="color: #ff0000;"><a href="https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/14-reisen/1378-bassano-tour-thermik-technik">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/14-reisen/1378-bassano-tour-thermik-technik</a></span></p>
